INSERT INTO `awards` VALUES (2,'Prof. (Dr.) Mohit Gangwar ','<ul>\r\n	<li><strong>Principal of Bhabha Engineering Research Institute</strong>, Bhopal, Madhya Pradesh&nbsp;received &quot;<strong>Excellent Educationalist Icon Award 2020&quot;</strong>&nbsp;for Excellent work in the field of Education by <strong>Uttar Pradesh World Records&nbsp;</strong>- Uttar Pradesh Book of Records.</li>\r\n	<li><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/92ad0286774e0b1836274608063204ea.jpeg\" style=\"height:400px; width:300px\" /></li>\r\n	<li><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/0701e0ebb35deeae721f30c2a74c4244.jpeg\" style=\"height:200px; width:150px\" /></li>\r\n	<li>&nbsp;</li>\r\n	<li>Academic Leadership of Engineering Institute as Young Principal and Research Work,&nbsp;<strong>India Star Independent Award 2020.</strong></li>\r\n	<li>&nbsp;</li>\r\n	<li><strong><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/7938a5c0a11d3c2d05426306d1b2db1f.jpg\" style=\"height:400px; width:300px\" /></strong></li>\r\n	<li>&nbsp;</li>\r\n	<li>For <strong> Research Excellence Award 2020&nbsp;</strong>given by G-Town Society</li>\r\n	<li>&nbsp;</li>\r\n	<li><strong><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/231b13c71639aeccbf841561341c2434.jpeg\" style=\"height:380px; width:300px\" /></strong></li>\r\n	<li>&nbsp;</li>\r\n	<li>Certificate Recieved from <strong>AICTE for Mentor under National Initative for Technical Teacher Training</strong>.</li>\r\n	<li>&nbsp;</li>\r\n	<li><span style=\"font-size:13px\"><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/c5581d53f3f0e0befbb85212bb058062.jpg\" style=\"height:557px; width:400px\" /></span></li>\r\n	<li>&nbsp;</li>\r\n	<li>Best Young Dean of the Year&nbsp;<strong>Global Excellence Recognition Awards 2019</strong>.</li>\r\n</ul>\r\n','86581e921e6f4fa0a39b6af8981a521e.jpg','2021-01-14 07:57:51');
INSERT INTO `awards` VALUES (3,'Dr. Sailesh Kumar Ghatuary ','<ul>\r\n	<li>Prof. (Dr.) Sailesh Kumar Ghatuary Honoured with prestigious award by &#39; Healthcopeia Foundation&#39; for &ldquo; <strong>Excellent Contribution in the field of Pharmaceutical&nbsp; education</strong>&rdquo;&nbsp; &amp; Research supported by Indian Pharmacopoeia Commission (IPC), Ministry of Health and Family Welfare and Indian Drug Manufacturers&#39; Association (IDMA) and in association with Sahara News Network&nbsp; in a grand Symposium under the name of&nbsp; <strong>&#39;HEALTHCARE LEADERSHIP CONCLAVE AND AWARDS</strong> &#39; on 25th November, 2021, at FICCI Federation House, New Delhi, Delhi 110001.</li>\r\n	<li><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/8b1f627b4e923cfef490b3ec6eac745d.jpeg\" style=\"width:500px\" /></li>\r\n	<li>&nbsp;</li>\r\n	<li>Indian Pharmaceutical Association awarded Prof.(Dr.) Sailesh Kumar Ghatuary&nbsp; as &ldquo; <strong>Eminent Principal Award</strong>&rdquo; on 4th October 2021 for his remarkable work &amp; service to the Pharmaceutical research field &amp; education.</li>\r\n	<li><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/96864af1d0248516c50d0d6dbd9a6b82.jpeg\" style=\"width:500px\" /></li>\r\n	<li><strong>Guest of honor American conference of research</strong>, Chennai</li>\r\n</ul>\r\n','2e0bba6f774891514ae04d8c9818a1d7.png','2021-12-08 10:31:04');
INSERT INTO `awards` VALUES (4,'Dr. Tripti Arjariya','<ul style=\"list-style-type:circle\">\r\n	<li>&nbsp;&ldquo;<strong>Shikshak Shri Award</strong> 2019&rdquo;, New Delhi.</li>\r\n	<li><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/c8e9968e464c2e489433654647f5b281.jpg\" style=\"height:270px; width:350px\" /></li>\r\n	<li>&nbsp;</li>\r\n	<li>The Real <strong>Super Women 2020</strong>&nbsp; by FSIA</li>\r\n	<li><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/5b5ad05dcf0a21293f1991c72e835959.jpg\" style=\"height:454px; width:350px\" /></li>\r\n</ul>\r\n\r\n<ul style=\"list-style-type:circle\">\r\n	<li><strong>&nbsp;&ldquo;Teacher Innovation Award 2019&rdquo;&nbsp;</strong>award received FROM ZIIEI ( SRI AUROBINDO SOCIETY PRESENT this award).</li>\r\n	<li><strong>&nbsp;&ldquo;Young Woman Educator &amp; Scholar&rdquo;&nbsp;</strong>08<sup>th</sup>&nbsp;MARCH (International Women&rsquo;s Day) 2020 at Coimbatore, Tamil Nadu.&nbsp;</li>\r\n	<li>&nbsp;&ldquo;<strong>Iron Lady Award 2019</strong>&nbsp;&ldquo;, New Delhi.</li>\r\n</ul>\r\n','c14058c0d52a680920e4619bd6af6134.jpg','2021-01-21 04:55:08');
