INSERT INTO `course` VALUES (47,3,'B.TECH LATERAL ENTRY',1,'<table border=\"\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td colspan=\"5\" style=\"height:61px; width:871px\">\r\n			<p><strong><span style=\"font-size:14px\"><span style=\"color:#cc6600\">COLLEGE - BHABHA ENGINEERING RESEARCH INSTITUTE, BHOPAL</span></span></strong></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:40px; width:93px\"><strong><span style=\"color:#3366ff\">COURSE</span></strong></td>\r\n			<td style=\"width:144px\"><strong><span style=\"color:#3366ff\">BRANCH</span></strong></td>\r\n			<td style=\"width:271px\"><strong><span style=\"color:#3366ff\">ELIGIBLE BRANCH OF QUALIFYING EXAM(DIPLOMA / GRADUATION) PASSED</span></strong></td>\r\n			<td style=\"width:99px\"><strong><span style=\"color:#3366ff\">DURATION</span></strong></td>\r\n			<td style=\"width:264px\"><strong><span style=\"color:#3366ff\">ELIGIBILITY</span></strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td rowspan=\"7\" style=\"height:700px; width:93px\"><strong>B.TECH LATERAL ENTRY</strong></td>\r\n			<td style=\"width:144px\"><strong>MECHANICAL ENGINEERING</strong></td>\r\n			<td style=\"width:271px\"><strong>MECHANICAL ENGINEERING/BSC/ADVANCE DIPLOMA IN TOOL &amp; DIEMAKING/AUTOMOBILE ENGINEERING/ CEMENT TECHNOLOGY/INDUSTRIAL PRODUCTION ENGINEERING (IPE)/MANUFACTURING ENGINEERING/ MECHATRONICS/ PRINTING TECHNOLOGY/PRODUCTION ENGINEERING/ REFRIGERATION &amp; AIRCONDITIONING</strong></td>\r\n			<td rowspan=\"7\" style=\"width:99px\"><strong>&nbsp;3 Years</strong></td>\r\n			<td rowspan=\"7\" style=\"width:264px\"><strong>Candidate must have passed a regular three year engineering diploma programme examination in appropriate branch of Engineering/ Technology&nbsp; from AICTE/UGC&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; OR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Passed B.Sc. Degree examination and have passed 12th examination with mathematics.Obtained at least 45% marks and 40% marks in case of SC, ST, OBC Madhya Pradesh .</strong><br />\r\n			&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:79px; width:144px\"><strong>COMPUTER SCIENCE ENGINEERING</strong></td>\r\n			<td style=\"width:271px\"><strong>COMPUTER ENGINEERING /COMPUTER SCIENCE/ COMPUTER SCIENCE &amp; ENGG/BSC/DIPLOMA IN COMPUTER HARDWARE AND MAINTENANCE/ INFORMATION TECHNOLOGY</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:105px; width:144px\"><strong>ELECTRONICS AND COMMUNICATION ENGG.</strong></td>\r\n			<td style=\"width:271px\"><strong>ELECTRONICS &amp; COMMUNICATION/ELECTRONICS AND TELECOMMUNICATION/ELECTRONICS/ELECTRONIC ENGINEERING/INFORMATION TECHNOLOGY/ MECHATRONICS / OPTO ELECTRONICS /BSC/ INSTRUMENTATION &amp; CONTROL/INDUSTRIAL ELECTRONICS&nbsp;</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:46px; width:144px\"><strong>ELECTRICAL ENGINEERING</strong></td>\r\n			<td style=\"width:271px\"><strong>ELECTRICAL/ELECTRICAL AND &nbsp;ELECTRONICS/BSC</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:110px; width:144px\"><strong>CIVIL ENGINEERING</strong></td>\r\n			<td style=\"width:271px\"><strong>CIVIL ENGINEERING /ARCHITECTURAL ASSISTANTSHIP/ ARCHITECTURE AND INTERIOR DESIGN/CONSTRUCTION TECHNOLOGY &amp; MANAGEMENT/MINING ENGINEERING/MINING AND MINE SURVEYING/ARCHITECTURE/TOWN PLANNING/BSC/CEMENT TECHNOLOGY</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:73px; width:144px\"><strong>ELECTRICAL AND ELECTRONICS ENGG.</strong></td>\r\n			<td style=\"width:271px\"><strong>ELECTRICAL/ELECTRICAL AND &nbsp;ELECTRONICS/ BSC/ INSTRUMENTATION &amp; CONTROL</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:138px; width:144px\"><strong>INFORMATION TECHNOLOGY</strong></td>\r\n			<td style=\"width:271px\"><strong>INFORMATION TECHNOLOGY/COMPUTER ENGINEERING /COMPUTER SCIENCE/COMPUTER SCIENCE &amp; ENGG/BSC/ ELECTRONICS &amp; INSTRUMENTATION/ELECTRONICS AND TELECOMMUNICATION / ELECTRONICS &amp; COMMUNICATION/ ELECTRONICS/ELECTRONIC ENGINEERING/DIPLOMA IN COMPUTER HARDWARE AND MAINTENANCE</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"5\" style=\"height:61px; width:871px\">\r\n			<p><strong><span style=\"font-size:14px\"><span style=\"color:#cc6600\">COLLEGE - RKDF COLLEGE OF ENGINEERING, BHOPAL</span></span></strong></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:66px; width:93px\"><strong><span style=\"color:#3366ff\">ELIGIBLE COURSE</span></strong></td>\r\n			<td style=\"width:144px\"><strong><span style=\"color:#3366ff\">BRANCH</span></strong></td>\r\n			<td style=\"width:271px\"><strong><span style=\"color:#3366ff\">ELIGIBLE BRANCH OF QUALIFYING EXAM(DIPLOMA / GRADUATION) PASSED</span></strong></td>\r\n			<td style=\"width:99px\"><strong><span style=\"color:#3366ff\">DURATION</span></strong></td>\r\n			<td style=\"width:264px\"><strong><span style=\"color:#3366ff\">ELIGIBILITY</span></strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td rowspan=\"6\" style=\"height:633px; width:93px\"><strong>B.TECH LATERAL ENTRY</strong></td>\r\n			<td style=\"width:144px\"><strong>MECHANICAL ENGINEERING</strong></td>\r\n			<td style=\"width:271px\"><strong>MECH