INSERT INTO `events` VALUES (4,'Celebrating 62nd National Pharmacy Week at Bhabha University, Bhopal! ','Celebration & Special Events','Join us from Dec 11th to 16th, 2023, as we embrace the theme \'Join the Pharmacist to Ensure Patient Safety.\'','<div class=\"xdj266r x11i5rnm xat24cr x1mh8g0r x1vvkbs x126k92a\" style=\"margin: 0px; overflow-wrap: break-word; white-space-collapse: preserve; font-family: \">\r\n<div dir=\"auto\" style=\"font-family: inherit;\">Celebrating 62nd National Pharmacy Week at Bhabha University, Bhopal! <span style=\"font-family:inherit\"><img alt=\"????\" class=\"xz74otr\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t1e/1/16/1f33f.png\" style=\"border:0px; height:16px; object-fit:fill; width:16px\" /></span><span style=\"font-family:inherit\"><img alt=\"????\" class=\"xz74otr\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tbe/1/16/1f3c6.png\" style=\"border:0px; height:16px; object-fit:fill; width:16px\" /></span></div>\r\n\r\n<div dir=\"auto\" style=\"font-family: inherit;\">Join us from Dec 11th to 16th, 2023, as we embrace the theme &#39;Join the Pharmacist to Ensure Patient Safety.&#39;</div>\r\n\r\n<div dir=\"auto\" style=\"font-family: inherit;\">Engage in exciting events like cricket, chess, carrom, and more.</div>\r\n\r\n<div dir=\"auto\" style=\"font-family: inherit;\">Let&#39;s come together for awareness campaigns, cultural activities, and academic competitions.</div>\r\n\r\n<div dir=\"auto\" style=\"font-family: inherit;\">Be part of this enriching week, promoting healthcare excellence. <span style=\"font-family:inherit\"><img alt=\"????\" class=\"xz74otr\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t3d/1/16/1f3c5.png\" style=\"border:0px; height:16px; object-fit:fill; width:16px\" /></span><span style=\"font-family:inherit\"><img alt=\"????\" class=\"xz74otr\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t8c/1/16/1f389.png\" style=\"border:0px; height:16px; object-fit:fill; width:16px\" /></span></div>\r\n</div>\r\n\r\n<div class=\"x11i5rnm xat24cr x1mh8g0r x1vvkbs xtlvy1s x126k92a\" style=\"margin: 0.5em 0px 0px; overflow-wrap: break-word; white-space-collapse: preserve; font-family: \">\r\n<div dir=\"auto\" style=\"font-family: inherit;\"><span style=\"font-family:inherit\"><a class=\"x1i10hfl xjbqb8w x6umtig x1b1mbwd xaqea5y xav7gou x9f619 x1ypdohk xt0psk2 xe8uvvx xdj266r x11i5rnm xat24cr x1mh8g0r xexx8yu x4uap5 x18d9i69 xkhd6sd x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz xt0b8zv x1fey0fg\" href=\"http://www.bhabhauniversity.edu.in/\" rel=\"nofollow noreferrer\" style=\"color: var(--blue-link); cursor: pointer; text-decoration-line: none; outline: none; border-width: 0px; border-style: initial; border-color: initial; list-style: none; margin: 0px; text-align: inherit; padding: 0px; box-sizing: border-box; background-color: transparent; -webkit-tap-highlight-color: transparent; touch-action: manipulation; display: inline; font-family: inherit;\" tabindex=\"0\" target=\"_blank\">www.bhabhauniversity.edu.in</a></span></div>\r\n</div>\r\n','99e9fa035adf4a39eb6ae5eb42fc46e3.jpg');
INSERT INTO `events` VALUES (6,'Impact Lecture Series 2022-2023','Lecture Series','Afternoon session, \"Entrepreneurship & Innovation as Career opportunity \"\r\n','<p><strong><span style=\"color:rgb(5, 5, 5); font-family:segoe ui historic,segoe ui,helvetica,arial,sans-serif; font-size:15px\">Impact Lecture Series 2022-23</span></strong></p>\r\n\r\n<p><span style=\"color:rgb(5, 5, 5); font-family:segoe ui historic,segoe ui,helvetica,arial,sans-serif; font-size:15px\">IIC-4.0</span></p>\r\n\r\n<p><span style=\"color:rgb(5, 5, 5); font-family:segoe ui historic,segoe ui,helvetica,arial,sans-serif; font-size:15px\">MOE&#39;S Innovation Cell (MIC), AICTE</span></p>\r\n\r\n<p>Online Mode - Phase 2</p>\r\n\r\n<p>Session -1</p>\r\n\r\n<p>&quot;Entrepreneurship &amp; Innovation as Career opportunity&nbsp;&quot;</p>\r\n\r\n<p><span style=\"color:rgb(5, 5, 5); font-family:segoe ui historic,segoe ui,helvetica,arial,sans-serif; font-size:15px\">Bhabha Engineering Research Institute, Bhopal</span></p>\r\n\r\n<p><strong><span style=\"color:rgb(5, 5, 5); font-family:segoe ui historic,segoe ui,helvetica,arial,sans-serif; font-size:15px\">EMINENT SPEAKER</span></strong><br />\r\n<span style=\"color:rgb(5, 5, 5); font-family:segoe ui historic,segoe ui,helvetica,arial,sans-serif; font-size:15px\">Dr. Rajeev Gupta</span><br />\r\n<span style=\"color:rgb(5, 5, 5); font-family:segoe ui historic,segoe ui,helvetica,arial,sans-serif; font-size:15px\">Pro-VC</span><br />\r\n<span style=\"color:rgb(5, 5, 5); font-family:segoe ui historic,segoe ui,helvetica,arial,sans-serif; font-size:15px\">RTU, Kota, Rajasthan</span><br />\r\n<br />\r\n<span style=\"color:rgb(5, 5, 5); font-family:segoe ui historic,segoe ui,helvetica,arial,sans-serif; font-size:15px\">Date: 24 June 2022</span><br />\r\n<span style=\"color:rgb(5, 5, 5); font-family:segoe ui historic,segoe ui,helvetica,arial,sans-serif; font-size:15px\">Time: 2 PM to 3:30 PM</span><br />\r\n<br />\r\n<strong><span style=\"color:rgb(5, 5, 5); fo