INSERT INTO `events` VALUES (44,'Civil Dept Seminar','Seminar & Workshop','on \"Rain water Harvesting System\"  2019','<p><strong>Topic &ndash;Rain water Harvesting System </strong></p>\r\n\r\n<p><strong>Detail</strong>-Rain water harvesting&nbsp;is a technique of collection and&nbsp;storage&nbsp;of&nbsp;rainwater&nbsp;into natural reservoirs or tanks, or the infiltration of surface&nbsp;water&nbsp;into subsurface aquifers (before it is lost as surface runoff). One method of&nbsp;rainwater harvesting&nbsp;is rooftop&nbsp;harvesting.</p>\r\n\r\n<p><strong>Chief guest &ndash;H.N. Golait</strong></p>\r\n','72ab835eff99550a58364e041e3c5829.jpg');
