INSERT INTO `events` VALUES (82,'IPR Awareness Program','Celebration & Special Events','\"IPR Awareness Program\" under AICTE-MoE\'s Innovation Cell, KAPILA & NIPAM .','<div class=\"x11i5rnm xat24cr x1mh8g0r x1vvkbs xdj266r x126k92a\" style=\"margin: 0px; white-space: pre-wrap; overflow-wrap: break-word; font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; color: rgb(5, 5, 5); font-size: 15px;\">\r\n<div dir=\"auto\" style=\"font-family: inherit;\">RKDF College of Technology, Bhabha University, Bhopal is going to organize &quot;IPR Awareness Program&quot; under AICTE-MoE&#39;s Innovation Cell, KAPILA &amp; NIPAM . Mr. Harsh Dubey will be the Resource Person of the program. Students will get a chance to gain knowledge about the rights given to persons over the creations of their minds, inventions, and artistic works in the form of trademarks, patents and copyright.</div>\r\n</div>\r\n\r\n<div class=\"x11i5rnm xat24cr x1mh8g0r x1vvkbs xtlvy1s x126k92a\" style=\"margin: 0.5em 0px 0px; white-space: pre-wrap; overflow-wrap: break-word; font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; color: rgb(5, 5, 5); font-size: 15px;\">\r\n<div dir=\"auto\" style=\"font-family: inherit;\">Kindly join the session on Monday, 16th January 2023 from 2 pm onwards.</div>\r\n</div>\r\n\r\n<div class=\"x11i5rnm xat24cr x1mh8g0r x1vvkbs xtlvy1s x126k92a\" style=\"margin: 0.5em 0px 0px; white-space: pre-wrap; overflow-wrap: break-word; font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; color: rgb(5, 5, 5); font-size: 15px;\">\r\n<div dir=\"auto\" style=\"font-family: inherit;\">Venue: Seminar Hall, Bhabha University, Bhopal</div>\r\n</div>\r\n\r\n<div class=\"x11i5rnm xat24cr x1mh8g0r x1vvkbs xtlvy1s x126k92a\" style=\"margin: 0.5em 0px 0px; white-space: pre-wrap; overflow-wrap: break-word; font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; color: rgb(5, 5, 5); font-size: 15px;\">\r\n<div dir=\"auto\" style=\"font-family: inherit;\">Contact: Prof. (Dr.) Ashok Jhala, Program Coordinator, <span style=\"font-family:inherit\"><img alt=\"????\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t57/1/16/1f4f1.png\" style=\"border:0px; height:16px; width:16px\" /></span>9926428002.</div>\r\n</div>\r\n\r\n<div class=\"x11i5rnm xat24cr x1mh8g0r x1vvkbs xtlvy1s x126k92a\" style=\"margin: 0.5em 0px 0px; white-space: pre-wrap; overflow-wrap: break-word; font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; color: rgb(5, 5, 5); font-size: 15px;\">\r\n<div dir=\"auto\" style=\"font-family: inherit;\">For more details,</div>\r\n\r\n<div dir=\"auto\" style=\"font-family: inherit;\">visit <span style=\"font-family:inherit\"><img alt=\"????\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tb3/1/16/1f517.png\" style=\"border:0px; height:16px; width:16px\" /></span> <span style=\"font-family:inherit\"><a class=\"x1i10hfl xjbqb8w x6umtig x1b1mbwd xaqea5y xav7gou x9f619 x1ypdohk xt0psk2 xe8uvvx xdj266r x11i5rnm xat24cr x1mh8g0r xexx8yu x4uap5 x18d9i69 xkhd6sd x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz xt0b8zv x1fey0fg\" href=\"http://bhabhauniversity.edu.in/?fbclid=IwAR2nWGLOQX_8O5B9rwq6I8fBZnR-g1zY9YvQ2xulgbFDhQWRgGMWzXuBKkk\" rel=\"nofollow noopener\" style=\"color: var(--blue-link); cursor: pointer; text-decoration-line: none; margin: 0px; text-align: inherit; padding: 0px; outline: none; border-width: 0px; border-style: initial; border-color: initial; -webkit-tap-highlight-color: transparent; box-sizing: border-box; list-style: none; touch-action: manipulation; background-color: transparent; display: inline; font-family: inherit;\" tabindex=\"0\" target=\"_blank\">http://bhabhauniversity.edu.in</a></span></div>\r\n</div>\r\n','2415754625cb0a3f16c9f7b59387b713.jpg');
