INSERT INTO `homepage_sections` VALUES (1,'hero_video','Hero Video & Stats Bar','AERIAL · BHOPAL CAMPUS','32 acres of<br><em>living, learning</em> landscape.','From the medical quadrangle to the engineering labs — a bird\'s-eye view of the community our students call home.','','new-media/image/hero/bhabha_2.mp4','','','{\"poster\":\"new-media/image/campus-aerial.png\",\"stats\":[{\"number\":\"8500\",\"suffix\":\"+\",\"commas\":true,\"label\":\"STUDENTS\"},{\"number\":\"750\",\"suffix\":\"+\",\"commas\":false,\"label\":\"FACULTY\"},{\"number\":\"85\",\"suffix\":\"+\",\"commas\":false,\"label\":\"PROGRAMS\"},{\"number\":\"25\",\"suffix\":\"\",\"commas\":false,\"label\":\"SCHOOLS\"},{\"number\":\"300\",\"suffix\":\"+\",\"commas\":false,\"label\":\"RECRUITERS\"},{\"number\":\"20000\",\"suffix\":\"+\",\"commas\":true,\"label\":\"ALUMNI\"},{\"number\":\"2500\",\"suffix\":\"+\",\"commas\":true,\"label\":\"PUBLICATIONS\"},{\"number\":\"32\",\"suffix\":\" ac\",\"commas\":false,\"label\":\"CAMPUS\"}]}',1,1,'2026-09-21 03:29:10');
INSERT INTO `homepage_sections` VALUES (2,'chancellor_welcome','Chancellor\'s Welcome','CHANCELLOR\'S MESSAGE','A legacy of <em>excellence</em>.<br>A vision for tomorrow.','','<p><strong>Dr. Sadhna Kapoor</strong> is the Chancellor of BHABHA University. A visionary and a selfless leader with exceptional entrepreneurial, interpersonal, social and administrative skills; Dr. Sadhna Kapoor is passionate about technology and innovation, community development, social service, and interdisciplinary teaching and research.</p>\n<p>She has been awarded the title of “Honorary Professor” by the Academic Union Oxford, UK, reflecting her global dedication to educational innovation and excellence.</p>','new-media/image/hero/sadhna-mam.mp4','“We bridge academic brilliance with industrial pragmatism.”','DR. SADHNA KAPOOR · CHANCELLOR','{\n    \"recognitions\": [\n        {\n            \"title\": \"UGC\",\n            \"label\": \"RECOGNISED\"\n        },\n        {\n            \"title\": \"NAAC\",\n            \"label\": \"A+ GRADE\"\n        },\n        {\n            \"title\": \"AICTE\",\n            \"label\": \"APPROVED\"\n        }\n    ]\n}',1,2,'2026-09-08 15:44:58');
INSERT INTO `homepage_sections` VALUES (3,'why_bhabha','Why Bhabha University','WHY BHABHA','A university built<br>for <em>impact.</em>','From accreditation to ecosystem — every dimension of the Bhabha experience is engineered for academic depth, global mobility and lifelong opportunity.','','','','','{\n    \"features\": [\n        {\n            \"icon\": \"fa fa-certificate\",\n            \"title\": \"NAAC & UGC Recognised\",\n            \"desc\": \"Accredited by NAAC; UGC recognised under 2(f) & 12(B).\"\n        },\n        {\n            \"icon\": \"fa fa-flask\",\n            \"title\": \"Research Excellence\",\n            \"desc\": \"120+ research labs, 250+ patents and 2,500+ publications.\"\n        },\n        {\n            \"icon\": \"fa fa-globe\",\n            \"title\": \"Global Collaborations\",\n            \"desc\": \"MoUs with 60+ international universities across 4 continents.\"\n        },\n        {\n            \"icon\": \"fa fa-mortar-board\",\n            \"title\": \"Outstanding Placements\",\n            \"desc\": \"98% placement rate with 300+ recruiters and packages up to ₹52 LPA.\"\n        },\n        {\n            \"icon\": \"fa fa-building-o\",\n            \"title\": \"Smart Campus\",\n            \"desc\": \"32-acre wifi-enabled green campus with smart classrooms.\"\n        },\n        {\n            \"icon\": \"fa fa-rocket\",\n            \"title\": \"Innovation Ecosystem\",\n            \"desc\": \"Incubation centre, student startups and industry mentoring.\"\n        }\n    ]\n}',1,3,'2026-09-21 03:29:10');
INSERT INTO `homepage_sections` VALUES (4,'virtual_tour','Virtual Tour Showcase','Explore Campus · 360° Drone View','Virtual Tour of <em>Bhabha Campus</em>','Experience our breathtaking 32-acre green campus from the sky. Explore world-class academic blocks, research labs, sports arenas, and vibrant student life — all from right here.','','new-media/image/hero/bhabha_1.mp4','','','{\n    \"poster\": \"new-media/image/campus-aerial.png\",\n    \"badge1\": \"Live Campus Video\",\n    \"badge2\": \"Bhopal, MP\",\n    \"cards\": [\n        {\n            \"title\": \"32-Acre Green Campus\",\n            \"sub\": \"Smart Classrooms, Wifi & Hostels\"\n        },\n        {\n            \"title\": \"Central Library & Labs\",\n            \"sub\": \"120+ Hi-Tech Labs & Digital Library\"\n        }\n    ]\n}',1,4,'2026-09-21 03:29:10');
INSERT INTO `homepage_sections` VALUES (5,'research_innovation','Research & Innovation','RESEARCH & INNOVATION','Knowledge that <em>moves</em> the<br>world forward.','From climate-resilient agriculture to AI in healthcare — our 120+ labs and research centres tackle the questions that matter most.','','new-media/image/research-students.png','','','{\"metrics\":[{\"target\":250,\"value\":\"250\",\"suffix\":\"+\",\"prefix\":\"\",\"commas\":false,\"label\":\"PATENTS FILED\"},{\"target\":2500,\"value\":\"2500\",\"suffix\":\"+\",\"prefix\":\"\",\"commas\":true,\"label\":\"PUBLICATIONS\"},{\"target\":85,\"value\":\"85\",\"suffix\":\"Cr\",\"prefix\":\"₹\",\"commas\":false,\"label\":\"ACTIVE GRANTS\"},{\"target\":60,\"value\":\"60\",\"suffix\":\"+\",\"prefix\":\"\",\"commas\":false,\"label\":\"GLOBAL MOUS\"}],\"highlight_icon\":\"fa fa-flask\",\"highlight_text\":\"Featured: DST-funded sustainable energy research lab — ₹2.4 Cr grant.\",\"button_text\":\"EXPLORE RESEARCH →\",\"button_url\":\"research.php\"}',1,5,'2026-09-21 03:29:10');
INSERT INTO `homepage_sections` VALUES (6,'global_network','Global Network & MoUs','INTERNATIONAL','A truly <em>global</em> network.','60+ MoUs with leading universities across North America, Europe and Asia. Student exchange, joint research and dual degree pathways.','','','','','{\"tags\":[\"University of Toronto\",\"TU Munich\",\"NUS Singapore\",\"Monash\",\"Curtin\",\"UPenn\",\"Sheffield\",\"Kyoto University\",\"ETH Z\\u00fcrich\"],\"button_text\":\"APPLY NOW \\u2192\",\"button_url\":\"enquiry.php\"}',1,6,'2026-09-08 15:53:46');
INSERT INTO `homepage_sections` VALUES (7,'insta_reels','Campus Instagram Reels','LIFE AT BHABHA · INSTAGRAM REELS','Inside the <em>University</em>','Watch real campus moments, student celebrations, and university highlights directly from our official Instagram feed.','','','','','{\n    \"reels\": [\n        {\n            \"id\": \"reel-1\",\n            \"title\": \"Campus Celebrations & Events\",\n            \"code\": \"Dbr0ycHAi-x\",\n            \"embed_url\": \"https:\\/\\/www.instagram.com\\/p\\/Dbr0ycHAi-x\\/embed\\/\",\n            \"insta_url\": \"https:\\/\\/www.instagram.com\\/reel\\/Dbr0ycHAi-x\\/\"\n        },\n        {\n            \"id\": \"reel-2\",\n            \"title\": \"Annual Fest & Activities\",\n            \"code\": \"DanDix7AeZq\",\n            \"embed_url\": \"https:\\/\\/www.instagram.com\\/p\\/DanDix7AeZq\\/embed\\/\",\n            \"insta_url\": \"https:\\/\\/www.instagram.com\\/reel\\/DanDix7AeZq\\/\"\n        },\n        {\n            \"id\": \"reel-3\",\n            \"title\": \"Hi-Tech Skill Labs & Practical\",\n            \"code\": \"Dacmhdnj8hJ\",\n            \"embed_url\": \"https:\\/\\/www.instagram.com\\/p\\/Dacmhdnj8hJ\\/embed\\/\",\n            \"insta_url\": \"https:\\/\\/www.instagram.com\\/reel\\/Dacmhdnj8hJ\\/\"\n        },\n        {\n            \"id\": \"reel-4\",\n            \"title\": \"University Highlights & Moments\",\n            \"code\": \"DaSehWXDgwj\",\n            \"embed_url\": \"https:\\/\\/www.instagram.com\\/p\\/DaSehWXDgwj\\/embed\\/\",\n            \"insta_url\": \"https:\\/\\/www.instagram.com\\/reel\\/DaSehWXDgwj\\/\"\n        }\n    ]\n}',1,7,'2026-09-08 15:44:58');
INSERT INTO `infrastructure` VALUES (1,'AUDITORIUM & CONFERENCE FACILITY','<p style=\"text-align:justify\">Bhabha University firmly believes in providing its students exposure to national and international knowledge experts, through regular national and international conferences and workshops hosted in campus. It is with this view that a wide choice of modern conference facilities have been thoroughly planned and incorporated into the campus. Auditorium commonly used by students ,it has been built with centralized air conditioners , Wi-fi service and a spectacular stage along with green rooms and perfect amount of lighting. This auditorium is used for various events and conferences.</p>\r\n','2aa0d1727f2df6a9ddfa7bb009eb7873.jpg');
INSERT INTO `infrastructure` VALUES (2,'SMART CLASS ROOMS','<p style=\"text-align: justify;\">The classrooms are well designed to incorporate everything needed for a pleasant learning atmosphere. The wide spacious classrooms contain a white board and a projector that is used for teaching. As a result professors can switch to different modes of teaching as and when required so that the teaching isn&rsquo;t monotonous and the lectures are put across in the best way possible. This hi-tech equipment enables the faculty to conduct classes in a way that enable students to make use of every available resource at the click of a button. These classrooms are also often used for seminars and events from time to time.</p>\r\n','83e285d874ee031ad471ea4df94a1945.jpg');
INSERT INTO `infrastructure` VALUES (3,'CANTEEN','<p style=\"text-align:justify\">Bhabha University has been fully blessed with fully equipped multi cuisine canteens. canteens are on contract basis with external caterers and provide quality food at student friendly prices. Hosting a wide array of cuisines and dishes, they cater to the needs of the students from every place of country providing them home style food with no compromise on the quality.</p>\r\n','3864d09b8c0761c29ab3d67b49585238.jpg');
INSERT INTO `infrastructure` VALUES (4,'SOLAR PLANT','<p style=\"text-align: justify;\">Bhabha University installed 100KV significant solar power capacity into their grids to supplement or provide an alternative to conventional energy sources.</p>\r\n','ed3185628b9828212309305234c8a863.jpg');
INSERT INTO `infrastructure` VALUES (5,'COMMUNITY RADIO ','<p style=\"text-align: justify;\">The Radio club formed by our station consists of faculties, students and members of the local community. We conduct several activities amidst our community members and they too actively participate in our radio programme making and broadcasting. Radio Popcorn is the first Campus Radio in state of Madhya Pradesh. The CRS broadcasts for 10 hours every day and primarily focuses on providing information about educational opportunities and career guidance.</p>\r\n','9d2419cc88e43953ae02ef09e8d0bd2c.jpg');
INSERT INTO `infrastructure` VALUES (6,'SEMINAR HALL','<p style=\"text-align: justify;\">Seminars and workshops are a regular and integral part of the course curriculum at Bhabha University. For these purposes, we have a seminar hall enough to accommodate a large number of students, spacious and equipped with all modern technical aids including LCD and sound systems. This seminar hall is also used for student meets, guest lectures and screening of films.</p>\r\n','ead917cf834bc55c509c7229c90b39e3.jpg');
INSERT INTO `infrastructure` VALUES (7,'HEALTH CENTRE','<p style=\"text-align:justify\">Health centre facility is also available in University campus, where first aid facilities were extended to the students and regularly doctors visit for student &amp; staff health issues. University has well-furnished primary health center has well experienced qualified doctor &amp; staff.</p>\r\n','e24d4326ba8712763cc0e1484f66dc4d.jpg');
INSERT INTO `infrastructure` VALUES (8,'Wi-Fi CAMPUS','<p style=\"text-align:justify\">WiFi Campus. The entire campus is Wi-Fi enabled with a high speed internet connection to allow the students to access the internet no-matter wherever they are. The coverage of Wi-Fi is not only restricted to class rooms but also extends to all the areas including library, Auditorium, cafeteria, and hostels.</p>\r\n','adefd4e53054c616c24d6bd83c5b3aaf.jpg');
INSERT INTO `infrastructure` VALUES (9,'CENTRAL COMPUTER LAB','<p style=\"text-align:justify\">Bhabha University coordinates activities in central computer lab to ensure that students have access to and assistance in the use of computer technology. Hires, trains and supervises student help, work-study and casual employees that support the computer labs.</p>\r\n','b6123df20111594aa04d8b15dd6ce2af.jpg');
INSERT INTO `infrastructure` VALUES (10,'CENTRAL LIBRARY','<p style=\"text-align:justify\">The library is well furnished in a big hall having curtains at windows &amp; doors. There is separate study room for staff members. The books are available for various branches for study purpose.</p>\r\n\r\n<p><strong>The Library contains:-</strong></p>\r\n\r\n<ol>\r\n	<li>All the syllabus books for all branches.</li>\r\n	<li>Tables and chairs for sitting about 100 students at a time.</li>\r\n	<li>Magazines and Newspapers</li>\r\n	<li>Previous year question papers.</li>\r\n	<li>Books for general knowledge and current affairs.</li>\r\n	<li>Internet connection.</li>\r\n</ol>\r\n','acacb02dda9b764fac164d4397a2accd.jpg');
INSERT INTO `infrastructure` VALUES (11,'PARKING FACILITY','<p style=\"text-align:justify\">University campus provides parking facility for both students &amp; staff</p>\r\n','47935d389e5e3fde4a901da4e0d5fd4a.jpg');
INSERT INTO `infrastructure` VALUES (12,'CCTV SECURE CAMPUS','<p style=\"text-align:justify\">University campuses feature a variety of buildings, each with their own security needs. Campus security cameras help to secure these facilities, watching for suspicious behavior and unauthorized access.</p>\r\n','a21a86aaaa2a4e2d73c247cdb15af08e.jpg');
INSERT INTO `infrastructure` VALUES (13,'GYM','<p style=\"text-align:justify\">Bhabha University provides affordable and highly specified gymnasia for students &amp; staff. We have a modern gym for your modern lifestyle.</p>\r\n','08ba91f6cd604afe6629e3c47afc8dfa.jpg');
INSERT INTO `infrastructure` VALUES (14,'HOSTEL','<p style=\"text-align:justify\">University has well designed two hostels one for boys and one for girls with all modern facilities, for the boarding and other recreational activities. The hostels have their own mess to provide good and hygienic food to the students. Both hostels have common Rooms, Volleyball ground, badminton court and facilities for other indoor games.</p>\r\n\r\n<p><strong>Common Room</strong></p>\r\n\r\n<p style=\"text-align:justify\">Spacious common rooms are provided in both the hostels, which are a place for constructive activities like indoor games, discussions and get together within the hostel. Indoor games like carom board, table tennis are provided within the hostels.</p>\r\n\r\n<p><strong>Rooms</strong></p>\r\n\r\n<p style=\"text-align:justify\">Well furnished and spacious rooms are there for students in each hostel. Each room is equipped with a bed, a study table, study chair and almirah.</p>\r\n','f26b29937f258d4966b0be4de6bea02d.jpg');
INSERT INTO `infrastructure` VALUES (15,'STAFF QUARTER','<p style=\"text-align:justify\">There is a staff colony in the Institute campus for staff members. The houses including Principal residence, Guest House, houses for HOD, for Senior Lecturer, Lecturer, houses for Class-III employees, houses for Class-IV. The staff colony has two lush green parks along with light facility in the park and streets</p>\r\n','fc437190548509a180202e5c3a7a3aa3.png');
INSERT INTO `infrastructure` VALUES (16,'TRANSPORTATION','<p style=\"text-align:justify\">Bhabha University has taken all efforts to ensure the commuting of students both inside &amp; outside-as comfortable and accessible as possible. The university buses transport al students from and to all location in an around Bhopal. This helps day scholar and local residents reach college on time. Cabs &amp; BRTS buses run all around the college during all the active hours of the day.</p>\r\n','1861bfeabedd25b52f2192d45a03c7f7.jpg');
