INSERT INTO `page` VALUES (1,'University Account Details','university-account-details','Admissions','University Account Details','<p style=\"text-align:justify\">Respected Parents/Students of Bhabha University are requested to deposit their Tution Fee directly in Union Bank of India, RKDF College Bhopal or through RTGS/NEFT and receipt given to account section of Bhabha University. The Bank details are as under :-</p>\r\n\r\n<h3>Fee Payment Through :</h3>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\"><strong>Account Name : Bhabha University</strong></li>\r\n	<li><strong>Account Number : 573801010050206 </strong></li>\r\n	<li><strong>IFSC CODE :&nbsp; UBIN0557382</strong></li>\r\n	<li><strong>Bank Name : Union Bank of India</strong></li>\r\n	<li><strong>Branch : RKDF College Bhopal</strong>\r\n	<hr /></li>\r\n</ul>\r\n\r\n<p><strong>Fee Payment Through</strong> : <strong><a href=\"http://m.p-y.tm/bhabhauniversity_nrweb\" target=\"_blank\"><span style=\"color:#3366ff\">Online PayTM</span></a></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Fee Payment Through</strong> : <strong><span style=\"color:#0066ff\"> Scan&nbsp;PayTM QR Code&nbsp;</span></strong></p>\r\n\r\n<p><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/1ef67ce983b17dbdf127b7a85f3fb57e.jpeg\" style=\"height:289px; width:289px\" /></p>\r\n<!--<p>Click here : <strong><a href=\"https://www.bhabhauniversity.edu.in/page/2/\"><span style=\"color:#FF0000\">Online Fee Payment</span></a></strong></p> -->\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n',1);
