INSERT INTO `page` VALUES (10,'Conference /Seminar/ILS-IIC 4.0','conference-seminar-ils-iic-4-0','Research','Conference /Seminar/ILS-IIC 4.0','<p>&nbsp;</p>\r\n\r\n<h1 style=\"text-align:center\"><strong><span style=\"color:#B22222\">Impact Lecture Series Phase-II</span></strong></h1>\r\n\r\n<h1 style=\"text-align:center\"><a href=\"https://www.youtube.com/watch?v=QVg2ca0HBc8\"><span style=\"color:#B22222\">Entrepreneurship &amp; Innovation as Career Opportunity </span></a></h1>\r\n\r\n<p><span style=\"font-size:14px\"><!-- <p><strong> INTERNATIONAL / NATIONAL CONFERENCE </strong></p>\r\n--></span></p>\r\n\r\n<hr />\r\n<h1 style=\"text-align:center\"><strong><span style=\"color:#0000CD\">1<sup>st</sup>&nbsp;INTERNATIONAL CONFERENCE </span></strong></h1>\r\n\r\n<p style=\"text-align:center\"><strong>ON</strong></p>\r\n\r\n<h3 style=\"text-align:center\"><strong><span style=\"color:#0000FF\">EMERGING TRENDS IN MULTI&nbsp; DISCIPLINARY RESEARCH </span></strong></h3>\r\n\r\n<h4 style=\"text-align:center\"><span style=\"color:#FF0000\">ETIMDR - 2021 </span></h4>\r\n\r\n<p style=\"text-align:center\"><strong><span style=\"color:#FFD700\">06-07 August&nbsp; 2021</span></strong></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"color:#0000CD\"><strong>OUR ESTEEMED KEY NOTE SPEAKER</strong></span></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"OUR ESTEEMED KEY NOTE SPEAKERS\" src=\"https://www.bhabhauniversity.edu.in/upload/media/5a1ed665435f17b8d1468b0d6dadb398.jpg\" style=\"border-style:solid; border-width:1px; height:690px; width:819px\" /></p>\r\n\r\n<div style=\"text-align: center;\"><strong>Paper on any of the theme of the conference should reach the convener of the&nbsp; conference on or before deadline at&nbsp; &nbsp; &nbsp;<span style=\"color:#FF0000\">conferencebhabha@gmail.com</span></strong></div>\r\n\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n\r\n<div style=\"text-align: center;\"><strong><span style=\"color:#FF0000\">Important Dates&nbsp;</span></strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>Abstract Submission Deadline&nbsp; :&nbsp; &nbsp;22 July 2021</strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>&nbsp; &nbsp;Paper Submission Deadline&nbsp; &nbsp; &nbsp; :&nbsp; &nbsp;27&nbsp; July&nbsp; 2021</strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>&nbsp; Acceptance Notification&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; :&nbsp; &nbsp;28&nbsp; July 2021</strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>Registration&nbsp; Deadline&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;:&nbsp; &nbsp;31&nbsp; July 202</strong></div>\r\n\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n\r\n<div>\r\n<div style=\"text-align: center;\"><strong><span style=\"color:#FF0000\">Help Desk</span></strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>&nbsp;Dr. Kavita Padegaonkar&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - 9993289569&nbsp;</strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>&nbsp;Mr. Arvind&nbsp; Singh Rajput&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - 9713806383&nbsp;</strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>Ms Abhilasha&nbsp; Diwedi&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- 7024612817</strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>Ms Sweta Sanodiya&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - 8720856060</strong></div>\r\n\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n\r\n<div style=\"text-align: center;\"><strong><span style=\"color:#FF0000\">Organizing secretary</span></strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>&nbsp;Dr. Deepa Bakhshi</strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>&nbsp;Director and Dean&nbsp;</strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>&nbsp;Bhabha University&nbsp;</strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>7000820896, </strong></div>\r\n\r\n<div style=\"text-align: center;\"><strong>berimcabpl@gmail.com</strong></div>\r\n\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\"><strong><strong>Registration link for conference click here : <a href=\"https://forms.gle/msoWJUUJbLhD8wx98\" onclick=\"window.open(this.href, \'REGISTRATIONFORM\', \'resizable=no,status=no,location=no,toolbar=no,menubar=no,fullscreen=no,scrollbars=yes,dependent=yes,width=500,left=35,height=600,top=25\'); return false;\"><span style=\"color:#FF0000\">REGISTRATION FORM</span></a></strong></strong></p>\r\n\r\n<p style=\"text-align:center\"><strong>BROCHURE</strong> <a href=\"https://www.bhabhauniversity.edu.in/upload/media/f99ae3e4f7a457403dc527af1e69ea87.pdf\"><span style=\"color:#cc6600\">DOWNLOAD</span></a></p>\r\n\r\n<hr />\r\n<p><strong>&nbsp;</strong></p>\r\n',1);
