INSERT INTO `research_portal` VALUES (6,'patents_publications','Patents, Publications & Scholarly Records','Scholarly Records','fa fa-database','Patents, Publications & <em>Research Papers</em>','Verified repository of filed patents, indexed papers (Scopus, UGC CARE), and authored book chapters.','','','{\"tab1_title\":\"Patent Filing Records\",\"tab1_desc\":\"Official patent applications submitted by university faculty and researchers.\",\"tab1_tag\":\"Format: IPO Indian Patent Office\",\"tab1_empty\":\"Official patent filing data will be updated upon departmental submission.\",\"tab2_title\":\"Research Paper List\",\"tab2_desc\":\"Papers indexed in Scopus, SCIE, UGC Care Group I & II, and PubMed journals.\",\"tab2_tag\":\"Indexed Repository\",\"tab2_empty\":\"Official publications list will be updated upon departmental submission.\",\"tab3_title\":\"Books & Chapters Published\",\"tab3_desc\":\"Authored reference textbooks and chapters published by recognized national and international publishers.\",\"tab3_empty\":\"Official authored books and chapters records will be updated upon departmental submission.\"}',1,6,'2026-09-09 05:35:40');
